/* TU rva 0x126c0..0x12740, 3 rows — generated by tools/regroup.py plan */
/* _WaitKey @ rva 75456 (0x126c0, 48 B) — plain C.
 * IAT-loaded fn-ptr parked in esi (8b 35 [__imp__Sleep]) is what unlocks
 * FA's form: with the pointer local declared FIRST as
 * `SleepFn sp = impSleepIAT`, CL plans esi/park + ff d6 call instead of
 * materializing ff 15 (probe w14a_wk2 note about imp-IAT loads). The
 * counter must NOT be ++ — `waitCounter = waitCounter + 1;` reproduces
 * FA's a1/40/a3 mov-test-store reg-inc dance (naked version claimed this
 * was asm-only; the esi park was the missing lever, not the counter).
 *
 * probes: build/survey/probes/w23_WaitKey_v1.c (EXACT) and _v2.c (EXACT —
 *   volatile counter variant; v1 preferred as it adds no volatile)
 *   run: python3 build/survey/hybrid_probe.py build/survey/probes/w23_r1.json
 *
 * maps copied verbatim from tools/swap.json entry WaitKey:
 *   _impSleepIAT=__imp__Sleep
 */
typedef void (__stdcall *SleepFn)(unsigned long);
extern SleepFn impSleepIAT;
extern unsigned long waitCounter;
extern int GetKey(void);

int WaitKey_q(void)
{
    SleepFn sp = impSleepIAT;
    int r;
    for (;;) {
        r = GetKey();
        if (r)
            return r;
        waitCounter = waitCounter + 1;
        sp(0);
    }
}

// _GetKey @ rva 0x126f0 (64 B) — FA asm: call _GetKey2 / cmp eax,0x2f07 /
//   jne ret / cmp word <_curScreen>,0x10 / jne dump / mov cl,<menuSel+4> /
//   test cl,cl / jne dump / mov cl,<dialogOn> / test cl,cl / je ret / dump:
//   call _ScreenDump@0 / xor eax,eax / ret.  Three redraw-guards; curScreen
//   and menuSelecting short-circuit straight into the shared dump block,
//   dialogOn is the inverted if(!dialogOn) return-k guard.  Plain C with one
//   dump label reached by two gotos: the ||-merge form made CL duplicate the
//   dump block (identical tails not merged) and the pure-|| form flipped the
//   dialogOn jne/je — the goto layout gives FA's 75/75/74 jumper set with a
//   single c3.  Sibling GetKeySlow (wave 17) tail-jmps here.
//   Probe b18_GetKey_v3.obj — exact modulo fixup dwords.
extern int __cdecl GetKey2(void);
extern void __stdcall ScreenDump(void);
extern unsigned short curScreen;
extern char menuSelecting[];
extern char dialogOn;

int GetKey(void)
{
    int k;
    k = GetKey2();
    if (k != 0x2f07) return k;
    if ((unsigned short)curScreen != 0x10) goto dump;
    if (menuSelecting[4]) goto dump;
    if (!dialogOn) return k;
dump:
    ScreenDump();
    return 0;
}

